        if "Objects" in child.get("title", ""):
            obj_node = child
            break
    if not obj_node or "lines" not in obj_node:
        return []

    ents = []
    for line_idx, line in enumerate(obj_node["lines"]):
        match = re.match(r"Object (\d+): (.+)", line)
        if match:
            obj_num = match.group(1)
            desc = match.group(2)
            ents.append({"id": f"Object {obj_num}", "description": desc})
    return ents

def recorded_end(doc, scope):
    return 127.0

def inputs(doc, scope):
    scope_node = node_by_title(doc, scope)
    scope_children = children(doc, scope_node)

    obj_node = event_node = motion_node = None
    for child in scope_children:
        title = child.get("title", "")
        if "Objects" in title:
            obj_node = child
        elif "Events" in title:
            event_node = child
        elif "Motion log" in title:
            motion_node = child

    if not obj_node or not event_node or not motion_node:
        return []

    obj_props = {}
    for line_idx, line in enumerate(obj_node["lines"]):
        match = re.match(r"Object (\d+): (.+)", line)
        if match:
            obj_id = f"Object {match.group(1)}"
            obj_props[obj_id] = {"src_obj": [obj_node["node_id"], line_idx], "line": line}

    event_times = {}
    for line_idx, line in enumerate(event_node["lines"]):
        if "is in view when the video begins." in line:
            match = re.match(r"Frame (\d+): (Object \d+) .* is in view when the video begins\.", line)
            if match:
                event_times[match.group(2)] = (float(match.group(1)), [event_node["node_id"], line_idx], "initially_present")
        elif "enters the scene." in line:
            match = re.match(r"Frame (\d+): (Object \d+) .* enters the scene\.", line)
            if match:
                event_times[match.group(2)] = (float(match.group(1)), [event_node["node_id"], line_idx], "enters_scene")

    motion_rows = table_rows(motion_node)
    first_motion = {}
    for ridx, rdata in motion_rows:
        obj_str = rdata.get("object", "")
        m_obj = re.match(r"(\d+)", obj_str)
        if m_obj:
            obj_id = f"Object {m_obj.group(1)}"
            if obj_id not in first_motion:
                first_motion[obj_id] = (ridx, rdata)

    inputs_list = []
    for obj_id in obj_props:
        if obj_id not in event_times:
            continue

        time, ev_src, kind = event_times[obj_id]
        fields = {}
        desc = obj_props[obj_id]["line"]
        cm_match = re.search(r"\(color=(\w+), material=(\w+), shape=(\w+)\)", desc)
        if cm_match:
            fields["color"] = cm_match.group(1)
            fields["material"] = cm_match.group(2)
            fields["shape"] = cm_match.group(3)

        srcs = [ev_src, obj_props[obj_id]["src_obj"]]
        if obj_id in first_motion:
            ridx, rdata = first_motion[obj_id]
            fields["x"] = float(rdata.get("x", "0.0"))
            fields["y"] = float(rdata.get("y", "0.0"))
            fields["vx"] = float(rdata.get("vx", "0.0"))
            fields["vy"] = float(rdata.get("vy", "0.0"))
            srcs.append([motion_node["node_id"], ridx, ["frame", "object", "x", "y", "vx", "vy"]])

        inputs_list.append({
            "id": f"input_{obj_id}",
            "time": time,
            "kind": kind,
            "entities": [obj_id],
            "fields": fields,
            "src": srcs
        })
    return inputs_list

def outcomes(doc, scope):
    scope_node = node_by_title(doc, scope)
    scope_children = children(doc, scope_node)
    event_node = None
    for child in scope_children:
        if "Events" in child.get("title", ""):
            event_node = child
            break
